#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8

int main(int argc, char *argv[])
{
    /* ---------- argument validation ---------- */
    if (argc < 3) {                     /* need at least N and M */
        puts("INVALID_INPUT");
        return 1;
    }

    /* parse N and M */
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n <= 0 || n > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    long m = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0' || m < 0 || m > n * (n - 1)) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* we expect exactly 2*m additional arguments */
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---------- graph construction ---------- */
    int adj[MAXV][MAXV] = {0};   /* adjacency matrix */
    int indeg[MAXV] = {0};
    bool done[MAXV] = {0};

    for (long i = 0; i < m; ++i) {
        long u = strtol(argv[3 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        long v = strtol(argv[3 + 2 * i + 1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        if (!adj[u][v]) {
            adj[u][v] = 1;
            indeg[v] += 1;
        }
    }

    /* ---------- Kahn's topological sort ---------- */
    int printed = 0;
    int order[MAXV];

    while (true) {
        int v = -1;
        for (int i = 0; i < n; ++i) {
            if (!done[i] && indeg[i] == 0) {
                v = i;
                break; // smallest index with indegree 0
            }
        }
        if (v == -1) break;
        order[printed++] = v;
        done[v] = true;
        for (int w = 0; w < n; ++w) {
            if (adj[v][w]) {
                adj[v][w] = 0;
                indeg[w]--;
            }
        }
    }

    if (printed != n) {
        puts("CYCLE");
        return 1;
    }

    /* ---------- output the ordering ---------- */
    for (int i = 0; i < printed; ++i) {
        if (i) putchar(' ');
        printf("%d", order[i]);
    }
    putchar('\n');
    return 0;
}
}
